def apply_complete_scoring(payload: dict[str, Any], complete: dict[str, Any]) -> None:
    del complete
    displayed_modules: list[str] = []
    for module_id in MODULE_SCORE_IDS:
        module = _module(payload, module_id)
        score = _number(module.get("综合得分"))
        displayed = score is not None and module_id in LEGACY_SCORE_TABLE_MODULES
        if not displayed:
            module["综合得分"] = None
            module["程度等级"] = None
            module["正式评分说明"] = None
            module.pop("评分解释", None)
        else:
            displayed_modules.append(module_id)
        module["score_valid"] = displayed
        module["完整评分值"] = score if displayed else None
        module["Word评分展示"] = displayed
        module["评分Profile"] = "当前结果重算的V0.1.1历史ECDF口径" if displayed else None
        module["评分状态说明"] = "当前结果重算" if displayed else "评分待标定"
    info = payload.setdefault("报告信息", {})
    info["评分模式"] = (
        "当前结果重算的V0.1.1历史ECDF口径"
        if displayed_modules
        else "评分待标定"
    )
    info["评分配置版本"] = info["评分模式"]
    info["综合得分"] = None
    info["程度等级"] = None
    info["Word评分展示范围"] = "/".join(displayed_modules) or "无"
    payload.pop("评分配置摘要", None)


