from __future__ import annotations

import hashlib
import json
import re
import sys
from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET

ROOT = Path(sys.argv[1]).resolve()
W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
A = "{http://schemas.openxmlformats.org/drawingml/2006/main}"
R = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}"
REL = "{http://schemas.openxmlformats.org/package/2006/relationships}"
FORBIDDEN = (
    "production_proxy_v1", "engineering proxy", "工程代理分", "调试",
    "/home/", "/tmp/", "frozen", "冻结数值", "clinic_current_payload",
)


def text_of(node: ET.Element) -> str:
    return "".join(x.text or "" for x in node.iter(f"{W}t"))


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def docx(path: Path) -> dict[str, object]:
    with ZipFile(path) as z:
        root = ET.fromstring(z.read("word/document.xml"))
        rel_root = ET.fromstring(z.read("word/_rels/document.xml.rels"))
        rels = {
            x.attrib.get("Id", ""): x.attrib.get("Target", "")
            for x in rel_root
            if x.attrib.get("Type", "").endswith("/image")
        }
        media = {
            name: digest(z.read(name))
            for name in z.namelist()
            if name.startswith("word/media/")
        }
        paragraphs = list(root.iter(f"{W}p"))
        visible = "\n".join(text_of(x) for x in paragraphs)
        drawing_rows: list[dict[str, object]] = []
        for p in paragraphs:
            ids = [x.attrib.get(f"{R}embed", "") for x in p.iter(f"{A}blip")]
            if ids:
                targets = [f"word/{rels[rid]}" for rid in ids]
                drawing_rows.append({
                    "text": text_of(p),
                    "count": len(ids),
                    "sha256": [media.get(target) for target in targets],
                })
        table_count = len(list(root.iter(f"{W}tbl")))
        bookmarks = [
            x.attrib.get(f"{W}name", "")
            for x in root.iter(f"{W}bookmarkStart")
            if x.attrib.get(f"{W}name", "") != "_GoBack"
        ]
        explanations = []
        for table in root.iter(f"{W}tbl"):
            rows = list(table.findall(f"{W}tr"))
            if not rows:
                continue
            header = [text_of(c).strip() for c in rows[0].findall(f"{W}tc")]
            if "结果解释" not in header:
                continue
            idx = header.index("结果解释")
            for row in rows[1:]:
                cells = row.findall(f"{W}tc")
                if idx < len(cells):
                    explanations.append(text_of(cells[idx]).strip())
        pair_rows = [x for x in drawing_rows if x["count"] == 2]
        return {
            "path": str(path),
            "sha256": digest(path.read_bytes()),
            "tables": table_count,
            "bookmarks": len(bookmarks),
            "modules": len([x for x in bookmarks if x.startswith("module_")]),
            "media": len(media),
            "explanation_rows": len(explanations),
            "blank_explanations": sum(not x for x in explanations),
            "forbidden": [x for x in FORBIDDEN if x.lower() in visible.lower()],
            "two_image_paragraphs": pair_rows,
            "red_base_caption": "左：红区底图；右：红区标注结果" in visible,
            "brown_base_caption": "左：棕区底图；右：棕区标注结果" in visible,
            "p90_gloss_unassessable": "P90油光强度: —" in visible,
            "visible_text": visible,
        }


def local_result(root: Path) -> dict[str, object]:
    idx = json.loads((root / "十二项检测结果索引.json").read_text(encoding="utf-8"))
    items = idx.get("十二项结果") or idx["items"]
    images = [img for item in items.values() for img in item.get("images", [])]
    missing = [x["path"] for x in images if not (root / x["path"]).is_file()]
    bad_hashes = [
        x["path"] for x in images
        if (root / x["path"]).is_file()
        and digest((root / x["path"]).read_bytes()) != x["sha256"]
    ]
    words = [docx(x) for x in sorted(root.glob("*.docx"))]
    structured = list(root.glob("*正式结构化数据.json"))
    return {
        "root": str(root),
        "profile": idx.get("capture_profile"),
        "status": idx.get("状态") or idx.get("status"),
        "success": idx.get("成功项目数") or sum(x.get("状态") == "success" for x in items.values()),
        "total": idx.get("项目总数") or len(items),
        "item_count": len(items),
        "image_roles": len(images),
        "missing_images": missing,
        "bad_image_hashes": bad_hashes,
        "structured_json": [str(x) for x in structured],
        "score_trace": [str(x) for x in root.glob("*评分追溯.json")],
        "word": words,
    }


def cloud_result(root: Path) -> dict[str, object]:
    bundle = json.loads((root / "cloud_response_bundle.json").read_text(encoding="utf-8"))
    raw_text = json.dumps(bundle, ensure_ascii=False)
    tasks = bundle.get("tasks") or bundle.get("worker_results") or bundle.get("results") or []
    if isinstance(tasks, dict):
        tasks = list(tasks.values())
    return {
        "root": str(root),
        "top_keys": list(bundle),
        "task_count": len(tasks),
        "forbidden": [x for x in FORBIDDEN if x.lower() in raw_text.lower()],
        "word": [docx(x) for x in sorted(root.glob("*.docx"))],
    }


def slim_word(x: dict[str, object]) -> dict[str, object]:
    return {k: v for k, v in x.items() if k != "visible_text"}


local_roots = sorted(
    p.parent for p in ROOT.rglob("十二项检测结果索引.json")
    if "institution-local/" not in str(p)
)
cloud_roots = sorted((ROOT / "cloud").glob("*"))
payload = {
    "local": [local_result(p) for p in local_roots],
    "cloud": [cloud_result(p) for p in cloud_roots if p.is_dir()],
}
for result in payload["local"] + payload["cloud"]:
    result["word"] = [slim_word(x) for x in result["word"]]
print(json.dumps(payload, ensure_ascii=False, indent=2))

