    """仅用于共享区域构建，防止 Mask 外像素影响鼻孔局部判断。"""
    safe = np.asarray(image).copy()
    valid = skin_mask > 0
    if np.any(valid):
        safe[~valid] = np.median(safe[valid], axis=0).astype(np.uint8)
    else:
        safe[:] = 0
    return safe


